import React from 'react';

const Hero = () => {
  const scrollToContact = () => {
    document.getElementById('contact').scrollIntoView({ behavior: 'smooth' });
  };

  return (
    <section id="home" className="hero">
      <div className="hero-content">
        <h1>Hi, I'm <span className="highlight">Rohith.R</span></h1>
        <p className="hero-subtitle">🌟 Machine Learning | LLM Agent Developer | Web Development 🌟</p>
        <p className="hero-description">Third-year B.Tech student specializing in AI & Data Science with strong technical foundation in programming and AI research</p>
        <div className="hero-buttons">
          <button onClick={scrollToContact} className="btn primary">Get In Touch</button>
          <a href="https://github.com/Cluster3824" className="btn secondary" target="_blank" rel="noopener noreferrer">
            <i className="fab fa-github"></i> GitHub
          </a>
        </div>
      </div>
    </section>
  );
};

export default Hero;
